@'
"""Small factorial example with one intentional boundary bug."""


def factorial(n):
    """Return n factorial for a non-negative integer n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 1:  # Intentional bug: zero is also a base case.
        return 1
    return n * factorial(n - 1)
'@ | Set-Content -LiteralPath factorial.py -Encoding utf8

@'
import unittest

from factorial import factorial


class FactorialTests(unittest.TestCase):
    def test_factorial_of_zero(self):
        self.assertEqual(factorial(0), 1)

    def test_factorial_of_one(self):
        self.assertEqual(factorial(1), 1)

    def test_factorial_of_five(self):
        self.assertEqual(factorial(5), 120)


if __name__ == "__main__":
    unittest.main()
